// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/TechWarn.ogg",
            "jb2a.zoning.inward.circle.once.bluegreen.01.01"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? triggerData.triggeringToken ?? reactorToken)
                .scaleToObject(1.5)
                .filter("Glow", { color: 0x7e8cff })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const target = triggerData.targets[0].target;

// -----------------------------------------------------------------------------
// TIER-SCALED HEAT
// -----------------------------------------------------------------------------
// {2/3/4} = Tier 1 / Tier 2 / Tier 3

const heat = api.tierValue(
    reactorToken,
    [2, 3, 4]
);

// -----------------------------------------------------------------------------
// REFRESH THIS PRIEST'S ABJURE ON THIS TARGET
// -----------------------------------------------------------------------------
// applyMark() stamps the effect with:
//
//     abjureSourceId: reactorToken.id
//
// This lets multiple Priests maintain independent Abjure effects while a
// repeated hit from the SAME Priest on the SAME target simply refreshes it.

const existingAbjures = api.findEffectsOnToken(
    target,
    "Abjure",
    {
        extraFlags: {
            abjureSourceId: reactorToken.id
        }
    }
);

for (const existingAbjure of existingAbjures) {
    await api.deleteEffect(
        target,
        existingAbjure
    );
}

// -----------------------------------------------------------------------------
// APPLY ABJURE
// -----------------------------------------------------------------------------
// The duration is tied to the affected character rather than the Priest.
//
// label: "end" + turns: 1 means the effect lasts until the END of the target's
// next turn. LA 4.1 automatically performs the necessary current-turn
// adjustment when the effect is applied during that target's turn.

await api.applyMark(
    reactorToken,
    [target],
    {
        effect: {
            name: "Abjure",
            icon: item.img,
            isCustom: true
        },

        note: `${heat} Heat each time this character makes an attack roll.`,

        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: target.id
        },

        flagKey: "abjureSourceId",

        extraOptions: {
            abjureHeat: heat
        }
    }
);

reactions.evaluate:
const hit = triggerData.targets?.[0];

if (!hit?.target || !hit.crit)
    return false;

// Find the attack-flow target entry belonging specifically to the character
// that was critically hit. This avoids assuming target array ordering.
const targetUuid = hit.target.document.uuid;

const targetEntry = triggerData.flowState?.data?.acc_diff?.targets?.find(
    entry => entry.targetUuid === targetUuid
);

if (!targetEntry)
    return false;

// Striker-Type only triggers against a target with NO cover.
return Number(targetEntry.cover ?? 0) === 0;

