// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/KineticImpact.ogg",
            "jb2a.impact.earth.01"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? reactorToken)
                .scaleToObject(1.4)
                .filter("Glow", { color: 0xff8a00 })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

// -----------------------------------------------------------------------------
// +2 BONUS DAMAGE
// -----------------------------------------------------------------------------
// onHit occurs before the pending damage roll, so this ephemeral bonus is
// carried directly into that attack's damage flow.

triggerData.flowState.injectBonus({
    name: "Striker-Type Critical Hit",
    type: "damage",
    damage: [
        {
            val: "2",
            type: "kinetic"
        }
    ]
});

// -----------------------------------------------------------------------------
// FREE BOOST
// -----------------------------------------------------------------------------
// Fire a genuine Boost activation first. This costs no action because the
// granted Boost is explicitly Free, but it means other automations that care
// about Boost can still see the action occur.

const boost = await api.executeSimpleActivation(
    reactorToken.actor,
    {
        title: "Boost",
        action: {
            name: "Boost",
            activation: "Free"
        },
        detail: "Granted by Striker-Type Critical Hit. Move up to your Speed."
    }
);

if (!boost.completed)
    return;

// -----------------------------------------------------------------------------
// BOOST MOVEMENT
// -----------------------------------------------------------------------------
// This is bonus movement granted by the trait, so it costs 0 movement from the
// actor's ordinary movement allowance.

const speed = reactorToken.actor.system.speed;

await api.moveToken(reactorToken, {
    range: speed,
    cost: 0,
    title: "STRIKER-TYPE BOOST",
    description: `Move up to ${speed} spaces. Cancel to remain in place.`
});

// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/AirBurst.ogg",
            "jb2a.explosion.01.orange"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? reactorToken)
                .scaleToObject(1.5)
                .filter("Glow", { color: 0xfff2b0 })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const target = triggerData.targets?.[0]?.target;

if (!target)
    return;

// -----------------------------------------------------------------------------
// CHOICE
// -----------------------------------------------------------------------------
// Blinding Shells is optional. Do not consume its 1/round use unless the Archer
// actually chooses to force the save.

const choice = await api.startChoiceCard({
    mode: "or",
    title: "BLINDING SHELLS",
    description: `<b>${reactorToken.name}</b> successfully attacked <b>${target.name}</b>. Use Blinding Shells?`,
    icon: "fas fa-sun",
    userIdControl: api.getActiveGMId(),
    choices: [
        {
            text: "Use Blinding Shells",
            icon: "fas fa-burst"
        },
        {
            text: "Ignore",
            icon: "fas fa-times"
        }
    ]
});

// Ignore, or the card was closed.
if (!choice || choice.choiceIdx !== 0)
    return;

// -----------------------------------------------------------------------------
// CONSUME 1/ROUND USE
// -----------------------------------------------------------------------------
// checkUsage:true reads the feature's native tg_round usage before offering
// this automation. Because this is activationMode:'instead', we consume the
// accepted use here rather than running the feature's native activation flow.

const currentUses = Number(
    item.system.uses_per_round?.value ?? 0
);

await item.update({
    "system.uses_per_round.value": currentUses + 1
});

// -----------------------------------------------------------------------------
// ENGINEERING SAVE + BLINDED
// -----------------------------------------------------------------------------
// executeSaveVsEffect handles the save and failed-save effect in one operation.
//
// The duration is tied to the affected character and therefore expires at the
// END of their next turn. LA 4.1 handles the current-turn adjustment itself.

await api.executeSaveVsEffect(
    target,
    {
        stat: "ENG",
        title: "Blinding Shells — Engineering Save",
        origin: reactorToken,

        effects: "Blinded",

        duration: { label: "indefinite" },

        extraFlags: {
            blindingShellsSourceItemId: item.id,
            blindingShellsAppliedTurnKey: game.combat
                ? game.combat.round + ":" + game.combat.turn
                : null
        },

        note: "Blinding Shells",
        sendToOwner: true
    }
);

reactions.evaluate:
const target = triggerData.triggeringToken ?? triggerData.token;
if (!target) return false;
const effects = api.findEffectsOnToken(target, "Blinded", { extraFlags: { blindingShellsSourceItemId: item.id } });
if (!effects.length) return false;
const currentTurnKey = game.combat ? game.combat.round + ":" + game.combat.turn : null;
return effects.some(effect => effect.flags?.["lancer-automations"]?.blindingShellsAppliedTurnKey !== currentTurnKey);

reactions.activationCode:
const target = triggerData.triggeringToken ?? triggerData.token;
if (!target) return;
await api.removeEffectsByNameFromTokens({
    tokens: [target],
    effectNames: ["Blinded"],
    extraFlags: { blindingShellsSourceItemId: item.id },
    notify: false
});

const playBreachRamFx = async () => {
    try {
        const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
        if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
            const files = ["modules/lancer-weapon-fx/soundfx/HeavyImpact.ogg", "jb2a.impact.earth.01"];
            await Sequencer.Preloader.preloadForClients(files);
            await new Sequence().sound().file(files[0]).volume(rtmFxApi.getEffectVolume(0.65)).effect().file(files[1]).atLocation(reactorToken).scaleToObject(2.1).filter("Glow", { color: 0xff6a00 }).play();
        }
    }
    catch (error) {
        console.warn("Breach Ram FX skipped; mechanics continue normally.", error);
    }
};

let breachRamMoveHook = Hooks.on("preUpdateToken", (document, change) => {
    if (document.uuid !== reactorToken.document.uuid)
        return;
    const startsMoving = Object.prototype.hasOwnProperty.call(change, "x") || Object.prototype.hasOwnProperty.call(change, "y");
    if (!startsMoving)
        return;
    Hooks.off("preUpdateToken", breachRamMoveHook);
    breachRamMoveHook = null;
    void playBreachRamFx();
});
// -----------------------------------------------------------------------------
// SUPERIOR RAM
// -----------------------------------------------------------------------------
// Superior Ram increases Breach Ram's movement to 10 spaces and gives characters
// +1 Difficulty on the Agility save against it.

const hasSuperiorRam = !!api.findItemByLid(
    reactorToken,
    "npcf_superior_ram_breacher"
);

const ramRange = hasSuperiorRam ? 10 : 6;

// -----------------------------------------------------------------------------
// BREACH RAM MOVEMENT
// -----------------------------------------------------------------------------
// Terrain/object destruction remains manual. moveToken gives us the special
// movement itself. LA 4.1.8's explicit forced action commits the chosen path
// through walls and characters as required by Breach Ram.

const moved = await api.moveToken(reactorToken, {
    range: ramRange,
    cost: 0,
    action: "forced",
    title: "BREACH RAM",
    description: `Move up to ${ramRange} spaces in a straight line. Resolve any obstructions in the path manually. Do not end this movement overlapping another character.`
});

if (breachRamMoveHook !== null) {
    Hooks.off("preUpdateToken", breachRamMoveHook);
    breachRamMoveHook = null;
}

if (!moved)
    return;

// -----------------------------------------------------------------------------
// SELECT CHARACTERS IN THE RAM'S PATH
// -----------------------------------------------------------------------------
// We keep this manual because the movement tool cannot reliably distinguish
// which occupied cells the Breacher actually passed through from arbitrary
// terrain/object interactions on the map.

const victims = await api.chooseToken(reactorToken, {
    count: -1,
    includeSelf: false,
    title: "BREACH RAM — TARGETS",
    description: "Select all characters that were in the Breacher's path."
});

if (!victims?.length)
    return;

// -----------------------------------------------------------------------------
// SUPERIOR RAM SAVE DIFFICULTY
// -----------------------------------------------------------------------------
// Instead of temporarily adding +1 Difficulty to EVERY victim, LA 4.1 lets the
// Superior Ram modifier live once on the Breacher and apply backwards to anyone
// making the relevant Agility save against them.

const superiorRamBonusId =
    `superior-ram-${reactorToken.id}-${foundry.utils.randomID()}`;

if (hasSuperiorRam) {
    await api.addGlobalBonus(
        reactorToken.actor,
        {
            id: superiorRamBonusId,
            name: "Superior Ram",
            type: "difficulty",
            val: 1,
            rollTypes: ["check"],
            applyToTargetter: true,

            context: {
                rammerTokenId: reactorToken.id
            },

            condition: (state, actor, data, context) => {
                const path = String(
                    data?.path ?? ""
                ).toLowerCase();

                return path.includes("agi") &&
                    state.la_extraData?.targetTokenId ===
                        context.rammerTokenId;
            }
        },
        {
            origin: reactorToken
        }
    );
}

// -----------------------------------------------------------------------------
// AGILITY SAVES
// -----------------------------------------------------------------------------
// executeForceCheck is deliberately retained here. Its saveVs option carries
// the Breacher's token ID through owner-routed save flows, allowing Superior
// Ram's applyToTargetter Difficulty to resolve correctly for player-owned tokens.

let saves;

try {
    saves = await api.executeForceCheck(
        "AGI",
        victims,
        {
            saveVs: reactorToken,
            sendToOwner: true,
            title: hasSuperiorRam
                ? "Breach Ram — Agility Save (+1 Difficulty)"
                : "Breach Ram — Agility Save"
        }
    );
}
finally {
    // The Superior Ram bonus only exists for these Breach Ram saves.
    if (hasSuperiorRam) {
        await api.removeGlobalBonus(
            reactorToken.actor,
            bonus => bonus.id === superiorRamBonusId
        );
    }
}

// -----------------------------------------------------------------------------
// FAILED SAVES
// -----------------------------------------------------------------------------

const failed = saves.results
    .filter(result =>
        result.completed && !result.passed
    )
    .map(result => result.token);

if (!failed.length)
    return;

// -----------------------------------------------------------------------------
// PUSH FAILED CHARACTERS OUT OF THE PATH
// -----------------------------------------------------------------------------
// A negative distance leaves the displacement unrestricted so the GM/player can
// place each character out of the Breacher's path as directly as possible.

await api.knockBackToken(failed, -1, {
    triggeringToken: reactorToken,
    actionName: "Breach Ram",
    item,
    title: "BREACH RAM — PUSH",
    description: "Move each failed character out of the Breacher's path as directly as possible."
});

// -----------------------------------------------------------------------------
// KNOCK FAILED CHARACTERS PRONE
// -----------------------------------------------------------------------------

await api.applyEffectsToTokens({
    tokens: failed,
    effectNames: ["prone"],
    note: "Breach Ram"
});

// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/MetallicThump.ogg",
            "jb2a.impact.earth.01"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? reactorToken)
                .scaleToObject(1.5)
                .filter("Glow", { color: 0xffb000 })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const combat = game.combat;

if (!combat)
    return;

// -----------------------------------------------------------------------------
// CURRENT TURN
// -----------------------------------------------------------------------------
// Break Armor cares about multiple successful attacks during the SAME turn.
// Store the combat, round, turn index, and active token so the tracker resets
// automatically whenever the combat advances to another turn.

const turnKey = [
    combat.id,
    combat.round,
    combat.turn,
    combat.current?.tokenId
].join(":");

let state = api.getActorFlags(
    reactorToken.actor,
    "breakArmorState"
) || {};

if (state.turnKey !== turnKey) {
    state = {
        turnKey,
        hitTargets: {}
    };
}

// -----------------------------------------------------------------------------
// PROCESS SUCCESSFUL DUAL SHOTGUN HITS
// -----------------------------------------------------------------------------

const newlyShredded = [];

for (const result of triggerData.targets ?? []) {
    const target = result.target;

    if (!target)
        continue;

    // Once a character is already Shredded there is nothing more for Break
    // Armor to track against them for the remainder of the scene.
    if (api.hasStatus(target, "shredded"))
        continue;

    // If this Breacher has already successfully attacked this target with the
    // Dual Shotguns during the current turn, this is the second hit and Break
    // Armor triggers.
    if (state.hitTargets[target.id]) {
        newlyShredded.push(target);
        continue;
    }

    // Otherwise remember this as the first successful attack this turn.
    state.hitTargets[target.id] = true;
}

// -----------------------------------------------------------------------------
// SAVE TURN STATE
// -----------------------------------------------------------------------------

await api.addActorFlags(
    reactorToken.actor,
    {
        breakArmorState: state
    }
);

if (!newlyShredded.length)
    return;

// -----------------------------------------------------------------------------
// APPLY SHREDDED
// -----------------------------------------------------------------------------
// No duration is supplied because Break Armor lasts for the rest of the scene.

await api.applyEffectsToTokens({
    tokens: newlyShredded,
    effectNames: ["shredded"],
    note: "Break Armor"
});

// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/PPC_Charge.ogg",
            "jb2a.shield.01.intro.blue"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(reactorToken)
                .scaleToObject(2)
                .filter("Glow", { color: 0x6bb7ff })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const targets = await api.chooseToken(reactorToken, {
    count: 1,
    range: reactorToken.actor.system.sensor_range,
    includeSelf: true,
    filter: token =>
        api.isFriendly(reactorToken, token) &&
        !api.findEffectOnToken(token, "Dispersal Shield"),
    filterWarning: "Dispersal Shield must target the Priest or an allied character that is not already protected by Dispersal Shield.",
    soft: false,
    title: "DISPERSAL SHIELD",
    description: "Choose the Priest or an allied character within Sensors."
});

if (!targets?.length)
    return;

const target = targets[0];

// -----------------------------------------------------------------------------
// TIER-SCALED OVERSHIELD
// -----------------------------------------------------------------------------

const shieldValue = api.tierValue(
    reactorToken,
    [5, 6, 7]
);

// -----------------------------------------------------------------------------
// APPLY OVERSHIELD DIRECTLY
// -----------------------------------------------------------------------------
// Overshield is independent of the one-hit Resistance. Once granted, it remains
// even after Dispersal Shield has protected against an attack and been consumed.
//
// Overshield does not stack, so retain whichever value is higher.

const currentOvershield = Number(
    target.actor.system.overshield?.value ?? 0
);

const newOvershield = Math.max(
    currentOvershield,
    shieldValue
);

if (newOvershield !== currentOvershield) {
    await target.actor.update({
        "system.overshield.value": newOvershield
    });
}

// -----------------------------------------------------------------------------
// APPLY ONE-HIT HALF-DAMAGE MODIFIER
// -----------------------------------------------------------------------------
// The bonus is stored on the protected character.
//
// applyToTargetter causes it to enter the damage flow of a character attacking
// this protected character, where it applies Half Damage to the protected
// target.
//
// We deliberately DO NOT use consumeOnUsage here. For applyToTargetter bonuses,
// the damage flow belongs to the attacker, so generic bonus-use consumption
// would look for the bonus on the wrong actor.
//
// Instead, the linked effect itself consumes one charge on onDamage after
// confirming that this exact Half Damage modifier participated in a HIT.

const bonusId = "dispersal-shield-half-" + item.id + "-" + target.id;

await api.removeGlobalBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);
await api.removeConstantBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);

await api.addConstantBonus(target.actor, {
    id: bonusId,
    name: "Dispersal Shield",
    type: "target_modifier",
    subtype: "half_damage",
    rollTypes: ["damage"],
    applyToTargetter: true,
    context: {
        dispersalShield: true,
        sourceItemId: item.id,
        sourcePriestTokenId: reactorToken.id,
        protectedTokenId: target.id
    }
});

await api.applyEffectsToTokens(
    {
        tokens: [target],
        effectNames: [{ name: "Dispersal Shield", icon: item.img, isCustom: true }],
        note: "Dispersal Shield — next successful attack deals half damage",
        duration: { label: "indefinite" },
        notify: false
    },
    {
        dispersalShield: true,
        dispersalShieldSourceItemId: item.id,
        dispersalShieldBonusId: bonusId
    }
);

reactions.evaluate:
const target = triggerData.target;
if (!target?.actor) return false;
const effects = api.findEffectsOnToken(target, "Dispersal Shield", { extraFlags: { dispersalShieldSourceItemId: item.id } });
return effects.some(effect => {
    const bonusId = effect.flags?.["lancer-automations"]?.dispersalShieldBonusId;
    return !!bonusId
        && !!triggerData.flowState?.la_extraData?.bonusUsage?.candidates?.[bonusId]
        && api.getConstantBonuses(target.actor).some(bonus => bonus.id === bonusId);
});

reactions.activationCode:
const target = triggerData.target;
if (!target?.actor) return;
const effects = api.findEffectsOnToken(target, "Dispersal Shield", { extraFlags: { dispersalShieldSourceItemId: item.id } });
for (const effect of effects) {
    const bonusId = effect.flags?.["lancer-automations"]?.dispersalShieldBonusId;
    if (bonusId) await api.removeConstantBonus(target.actor, bonusId);
}
await api.removeEffectsByNameFromTokens({
    tokens: [target],
    effectNames: ["Dispersal Shield"],
    extraFlags: { dispersalShieldSourceItemId: item.id },
    notify: false
});

// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/WeaponBeep.ogg",
            "jb2a.shield.01.intro.blue"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.35))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(reactorToken)
                .scaleToObject(1.5)
                .filter("Glow", { color: 0x4aa3ff })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const speed = reactorToken.actor.system.speed;

const moved = await api.moveToken(reactorToken, {
    range: speed,
    cost: 0,
    title: "DOUBLE TIME"
});

if (!moved)
    return;

// Optional presentation layer, following the guarded Sequencer/Lancer Weapon FX pattern used by the Lancer Automations 4.1.8 defaults.
try {
    const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/NexusFire.ogg",
            "jb2a.zoning.inward.circle.once.bluegreen.01.01"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? triggerData.triggeringToken ?? reactorToken)
                .scaleToObject(1.6)
                .filter("Glow", { color: 0x35ffd2 })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const target = triggerData.targets[0].target;

// -----------------------------------------------------------------------------
// TARGET CHOOSES DRONE BARRAGE EFFECT
// -----------------------------------------------------------------------------

const choice = await api.startChoiceCard({
    mode: "or",
    title: "DRONE BARRAGE",
    icon: "fas fa-satellite-dish",
    description:
        `<b>${target.name}</b> is caught in the Hive's drone barrage.<br><br>` +
        `Choose one:<br>` +
        `<b>• Immobilized + Impaired</b> until the end of your next turn.<br>` +
        `<b>• Forced Movement</b> up to 4 spaces in a direction chosen by ${reactorToken.name}.`,
    item,
    originToken: reactorToken,
    relatedToken: target,
    userIdControl: api.getTokenOwnerUserId(target),
    choices: [
        {
            text: "Immobilized + Impaired",
            icon: "fas fa-lock"
        },
        {
            text: "Move Up To 4 Spaces",
            icon: "fas fa-arrows-alt"
        }
    ]
});

if (!choice)
    return;

// -----------------------------------------------------------------------------
// OPTION 1 — IMMOBILIZED + IMPAIRED
// -----------------------------------------------------------------------------

if (choice.choiceIdx === 0) {
    await api.applyEffectsToTokens({
        tokens: [target],
        effectNames: [
            "immobilized",
            "impaired"
        ],
        note: "Drone Barrage",
        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: target.id
        }
    });

    return;
}

// -----------------------------------------------------------------------------
// OPTION 2 — FORCED MOVEMENT
// -----------------------------------------------------------------------------

if (choice.choiceIdx === 1) {
    await api.moveToken(target, {
        range: 4,
        free: true,
            title: "DRONE BARRAGE",
        description:
            `${reactorToken.name} moves ${target.name} up to 4 spaces. ` +
            `This is forced movement and does not provoke reactions.`
    });
}

const accDiff = triggerData.flowState?.data?.acc_diff;

if (!accDiff)
    return;

// -----------------------------------------------------------------------------
// CAP FINAL ACCURACY AT 0
// -----------------------------------------------------------------------------
// Dual Shotguns can benefit from Accuracy insofar as it cancels Difficulty,
// but the FINAL attack roll can never have positive Accuracy.
//
// At onAttack, the Accuracy/Difficulty HUD has already been confirmed, so each
// target's .total represents the final net Accuracy/Difficulty for that roll,
// including weapon modifiers, cover, Lock On, Prone, global bonuses, targeted
// bonuses, and any other modifiers already applied to the attack.
//
// If that final total is positive, add exactly enough Difficulty to reduce it
// to 0. Negative totals are left completely untouched.

for (const targetData of accDiff.targets ?? []) {
    const finalTotal = Number(targetData.total ?? 0);

    if (finalTotal <= 0)
        continue;

    targetData.difficulty =
        Number(targetData.difficulty ?? 0) + finalTotal;
}

// -----------------------------------------------------------------------------
// UNTARGED / BASE ROLL FALLBACK
// -----------------------------------------------------------------------------
// Normally Dual Shotguns will be rolled against targets, but preserve the same
// rule if Foundry ever resolves an untargeted/base attack roll.

if (!(accDiff.targets?.length)) {
    const baseTotal = Number(accDiff.base?.total ?? 0);

    if (baseTotal > 0) {
        accDiff.base.difficulty =
            Number(accDiff.base.difficulty ?? 0) + baseTotal;
    }
}

reactions.evaluate:
if (triggerData.triggeringToken?.id !== reactorToken.id)
