    },
    {
        eyeOfMidnightSource
    }
);

// Register Eye of Midnight as a persistent activated item. The TAH will
// provide the Quick Action below for ending the stance, which returns to
// this automation with triggerData.endActivation === true.
await api.setItemAsActivated(
    item,
    reactorToken,
    "Quick",
    "Deactivate Eye of Midnight"
);

