reactions.evaluate:
const mover = triggerData.triggeringToken ?? triggerData.token;

if (!mover)
    return false;

// Eye of Midnight must currently be active.
if (!api.getActivatedItems(reactorToken)?.some(i => i.id === item.id))
    return false;

// Only hostile movement can trigger Eye of Midnight.
if (!api.isHostile(reactorToken, mover))
    return false;

// Teleportation does not provoke this movement reaction.
if (triggerData.moveInfo?.isTeleport)
    return false;

const threat = 3;

// The tagged reroute has now completed at the first threatened space.
// This is where the "enter Threat" Overwatch actually resolves.
if (triggerType === "onMove") {
    const extra = triggerData.moveInfo?.extraData ?? {};

    return extra.eyeOfMidnightInterceptItemId === item.id
        && extra.eyeOfMidnightInterceptReactorId === reactorToken.id
        && extra.eyeOfMidnightInterceptMoverId === mover.id;
}

if (triggerType !== "onPreMove")
    return false;

// When Eye of Midnight reroutes an entering character to the first threatened
// space, that rerouted move is itself a new onPreMove. Let that move finish
// rather than intercepting it a second time.
const pendingIntercept = api.getActorFlags(
    reactorToken.actor,
    "eyeOfMidnightPendingIntercept"
);

if (
    triggerData.moveInfo?.isModified
    && pendingIntercept?.itemId === item.id
    && pendingIntercept?.moverId === mover.id
)
    return false;

// Ordinary Overwatch case: the mover already begins within Threat.
const startDistance = api.getMinGridDistance(
    mover,
    reactorToken,
    triggerData.startPos
);

if (startDistance <= threat)
    return true;

// Eye of Midnight also catches a hostile that enters Threat during its path,
// even if it began outside.
const path = triggerData.moveInfo?.pathHexes ?? [];
const startIndex = Math.max(0, path.historyStartIndex ?? 0);

for (let i = startIndex; i < path.length; i++) {
    const step = path[i];

    const distance = api.getMinGridDistance(
        mover,
        reactorToken,
        { x: step.x, y: step.y }
    );

    if (distance <= threat)
        return true;
}

return false;

reactions.activationCode:
const mover = triggerData.triggeringToken ?? triggerData.token;

if (!mover)
    return;

const threat = 3;

// If this is the tagged movement that brought the mover to the first
// threatened space, clear the temporary recursion guard immediately.
if (triggerType === "onMove") {
    await api.removeActorFlags(reactorToken.actor, {
        eyeOfMidnightPendingIntercept: true
    });
}

const shotgun = api.findItemByLid(
    reactorToken.actor,
    "npc-rebake_npcf_combat_shotgun_sentinel"
);

if (!shotgun) {
    ui.notifications.warn(
        `Eye of Midnight: Combat Shotgun not found on ${reactorToken.name}.`
    );
    return;
}

const fireShotgun = async () => {
    // Eye of Midnight has now actually been used as a Reaction.
    await api.setReaction(reactorToken, false);

    // Force the moving character to be the Combat Shotgun target.
    canvas.tokens.setTargets([mover.id]);

    await api.beginWeaponAttackFlow(
        shotgun,
        {},
        {
            overwatchAttack: true,
            eyeOfMidnight: true
        }
    );
};

const askToFire = async (description) => {
    const result = await api.startChoiceCard({
        mode: "or",
        title: "EYE OF MIDNIGHT — OVERWATCH",
        icon: api.getActivationIcon("reaction"),
        description,
        item,
        originToken: reactorToken,
        relatedToken: mover,
        userIdControl: api.getTokenOwnerUserId(reactorToken),
        choices: [
            {
                text: "Fire",
                icon: "fas fa-crosshairs"
            },
            {
                text: "Let Them Move",
                icon: "fas fa-person-running"
            }
        ]
    });

    return !!result && result.choiceIdx === 0;
};

// -----------------------------------------------------------------------------
// ENTERING THREAT — RESOLVE AFTER THE INTERCEPT MOVE
// -----------------------------------------------------------------------------

if (triggerType === "onMove") {
    await fireShotgun();
    return;
}

// -----------------------------------------------------------------------------
// MOVEMENT STARTS INSIDE THREAT — ORDINARY OVERWATCH TIMING
// -----------------------------------------------------------------------------

const startDistance = api.getMinGridDistance(
    mover,
    reactorToken,
    triggerData.startPos
);

if (startDistance <= threat) {
    const preConfirm = async () => {
        const fire = await askToFire(
            `<b>${mover.name}</b> is moving from within <b>${reactorToken.name}</b>'s Threat. Fire the Combat Shotgun?`
        );

        // Declined or card closed: allow the original movement normally.
        if (!fire)
            return false;

        // Ordinary Overwatch resolves before the triggering movement.
        await fireShotgun();

        // The attack has resolved; replay the triggering movement.
        return false;
    };

    triggerData.cancelTriggeredMove(
        `<b>${reactorToken.name}</b> may use Eye of Midnight against <b>${mover.name}</b>.`,
        false,
        api.getTokenOwnerUserId(mover),
        preConfirm,
        null,
        {
            item,
            originToken: reactorToken,
            relatedToken: mover
        }
    );

    return;
}

// -----------------------------------------------------------------------------
// MOVEMENT ENTERS THREAT — STOP AT THE FIRST THREATENED SPACE
// -----------------------------------------------------------------------------

const path = triggerData.moveInfo?.pathHexes ?? [];
const startIndex = Math.max(0, path.historyStartIndex ?? 0);

let interceptIndex = -1;

for (let i = startIndex; i < path.length; i++) {
    const step = path[i];

    const distance = api.getMinGridDistance(
        mover,
        reactorToken,
        { x: step.x, y: step.y }
    );

    if (distance <= threat) {
        interceptIndex = i;
        break;
    }
}

if (interceptIndex < 0)
    return;

const interceptPoint =
    path.getPathPositionAt?.(interceptIndex)
    ?? { x: path[interceptIndex].x, y: path[interceptIndex].y };

const preConfirm = async () => {
    const fire = await askToFire(
        `<b>${mover.name}</b> is about to enter <b>${reactorToken.name}</b>'s Threat. Fire the Combat Shotgun as they cross the line?`
    );

    // Declined or card closed: replay the original movement normally.
    if (!fire)
        return false;

    // Mark this specific reroute so its own onPreMove is allowed to finish.
    await api.addActorFlags(reactorToken.actor, {
        eyeOfMidnightPendingIntercept: {
            itemId: item.id,
            moverId: mover.id
        }
    });

    return true;
};

await triggerData.changeTriggeredMove(
    interceptPoint,
    {
        eyeOfMidnightInterceptItemId: item.id,
        eyeOfMidnightInterceptReactorId: reactorToken.id,
        eyeOfMidnightInterceptMoverId: mover.id
    },
    `<b>${mover.name}</b> stops as they enter <b>${reactorToken.name}</b>'s Threat.`,
    false,
    api.getTokenOwnerUserId(mover),
    preConfirm,
    null,
    {
        item,
        originToken: reactorToken,
        relatedToken: mover
    }
);

reactions.evaluate:
const triggeringToken = triggerData.triggeringToken ?? triggerData.token;
const currentTargetId = api.getActorFlags(
    reactorToken.actor,
    "followerCountTargetId"
);

// -----------------------------------------------------------------------------
// FOLLOWER COUNT TECH ATTACK
// -----------------------------------------------------------------------------

if (triggerType === "onInitTechAttack") {
    if (triggeringToken?.id !== reactorToken.id)
        return false;

    if (triggerData.techItem?.system?.lid !== item?.system?.lid)
        return false;

    const target = triggerData.targets?.[0];

    // The 4 Heat retarget cost only applies if Follower Count already has a
    // different target.
    return !!target
        && !!currentTargetId
        && currentTargetId !== target.id;
}

if (triggerType === "onTechHit") {
    return triggeringToken?.id === reactorToken.id
        && triggerData.techItem?.system?.lid === item?.system?.lid
        && !!triggerData.targets?.[0]?.target;
}

// -----------------------------------------------------------------------------
// FOLLOWER COUNT ENDS WHEN EITHER CHARACTER IS DESTROYED
// -----------------------------------------------------------------------------

if (triggerType === "onExitCombat") {
    return triggeringToken?.id === reactorToken.id;
}

if (triggerType === "onDestroyed") {
    if (!triggeringToken)
        return false;

    return triggeringToken.id === reactorToken.id
        || (!!currentTargetId && triggeringToken.id === currentTargetId);
}

return false;

reactions.activationCode:
const BOOST_ACTION = "Follower Count Boost";

const getCurrentTarget = () => {
    const targetId = api.getActorFlags(
        reactorToken.actor,
        "followerCountTargetId"
    );

    return targetId ? canvas.tokens.get(targetId) : null;
};

const tokenIsDestroyed = (token) => {
    if (!token?.actor)
        return true;

    return (token.actor.system.structure?.value ?? 1) <= 0
        || (token.actor.system.stress?.value ?? 1) <= 0;
};

// End the temporary Boost movement state while preserving the Breacher's
// ordinary movement allowance. The temporary cap is reduced to the amount
// actually spent by this Boost, so unused Boost movement cannot be spent later.
const endFollowerCountBoost = async () => {
    const boostActive = api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostActive"
    ) === true;

    if (!boostActive)
        return;

    const baseCap = Number(api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostBaseCap"
    ));

    const startCost = Number(api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostStartCost"
    ));

    if (Number.isFinite(baseCap) && Number.isFinite(startCost)) {
        const currentCost = Number(
            api.getIntentionalMoveData(reactorToken)?.cost ?? startCost
        );

        const boostCost = Math.max(0, currentCost - startCost);
        const desiredCap = baseCap + boostCost;
        const currentCap = Number(api.getMovementCap(reactorToken));

        if (Number.isFinite(currentCap) && currentCap !== desiredCap) {
            api.increaseMovementCap(
                reactorToken,
                desiredCap - currentCap
            );
        }
    }

    await api.removeActorFlags(reactorToken.actor, {
        followerCountBoostActive: true,
        followerCountBoostBaseCap: true,
        followerCountBoostStartCost: true
    });
};

const cleanupFollowerCount = async () => {
    await endFollowerCountBoost();

    const bonusId = api.getActorFlags(
        reactorToken.actor,
        "followerCountBonusId"
    );

    if (bonusId) {
        await api.removeGlobalBonus(
            reactorToken.actor,
            bonusId
        );
    }

    // Also clear any legacy/duplicate Follower Count bonuses left by the old
    // automation, which could stack Accuracy on repeated successful attacks.
    await api.removeGlobalBonus(
        reactorToken.actor,
        bonus => bonus.context?.followerCount === true
            && (
                !bonus.context?.sourceItemId
                || bonus.context.sourceItemId === item.id
            )
    );

    await api.removeExtraActions(item, BOOST_ACTION);
    await api.removeExtraActions(reactorToken.actor, BOOST_ACTION);

    const boostFeature = api.findItemByLid(
        reactorToken,
        "rtm_npcf_follower_count_boost"
    );
    if (boostFeature)
        await boostFeature.delete();

    await api.removeActorFlags(reactorToken.actor, {
        followerCountTargetId: true,
        followerCountBonusId: true,
        followerCountBoostUsedTurnKey: true,
        followerCountBoostRejected: true
    });

    await reactorToken.document.unsetFlag(
        "lancer-automations",
        "ownerActorUuid"
    );

    await reactorToken.document.unsetFlag(
        "lancer-automations",
        "ownerName"
    );
};

// -----------------------------------------------------------------------------
// RETARGET COST — PAY 4 HEAT BEFORE THE TECH ATTACK IS ATTEMPTED
// -----------------------------------------------------------------------------

if (triggerType === "onInitTechAttack") {
    const oldTarget = getCurrentTarget();

    // Defensive cleanup for stale state. If the old target no longer exists or
    // is already destroyed, Follower Count has ended and no Heat is owed.
    if (!oldTarget || tokenIsDestroyed(oldTarget)) {
        await cleanupFollowerCount();
        return;
    }

    // cancelTechAttack must be called before the first await. The preConfirm
    // resolves the Heat cost; returning false replays the original tech attack.
    const preConfirm = async () => {
        const result = await api.executeDamageRoll(
            reactorToken,
            [reactorToken],
            4,
            "Heat",
            "Follower Count — Retarget Cost"
        );

        // If the Heat flow itself did not complete, the cost was not paid and
        // the retarget attempt stays cancelled.
        if (!result?.completed)
            return true;

        // If paying the Heat destroyed the Breacher, it cannot continue with
        // the tech attack. Otherwise, replay it normally.
        return tokenIsDestroyed(reactorToken);
    };

    triggerData.cancelTechAttack(
        `<b>${reactorToken.name}</b> takes <b>4 Heat</b> to attempt to change Follower Count targets.`,
        "FOLLOWER COUNT — RETARGET",
        false,
        api.getTokenOwnerUserId(reactorToken),
        preConfirm,
        null,
        {
            item,
            originToken: reactorToken,
            relatedToken: triggerData.targets?.[0] ?? null
        }
    );

    await triggerData.cancelTechAttack.wait();
    return;
}

// -----------------------------------------------------------------------------
// SUCCESSFUL FOLLOWER COUNT — ESTABLISH/CHANGE THE TARGET
// -----------------------------------------------------------------------------

if (triggerType === "onTechHit") {
    const target = triggerData.targets?.[0]?.target;

    if (!target)
        return;

    // Follower Count grants exactly +1 Accuracy. Remove both the current bonus
    // and any legacy duplicate stacks before installing the new target bonus.
    await api.removeGlobalBonus(
        reactorToken.actor,
        bonus => bonus.context?.followerCount === true
            && (
                !bonus.context?.sourceItemId
                || bonus.context.sourceItemId === item.id
            )
    );

    const bonusId = await api.addGlobalBonus(
        reactorToken.actor,
        {
            name: "Follower Count",
            type: "accuracy",
            val: 1,
            rollTypes: ["attack"],
            applyTo: [target.id],
            context: {
                followerCount: true,
                sourceItemId: item.id,
                targetTokenId: target.id
            }
        },
        {
            duration: "indefinite",
            origin: reactorToken
        }
    );

    await api.addActorFlags(reactorToken.actor, {
        followerCountTargetId: target.id,
        followerCountBonusId: bonusId
    });

    // Keep the existing visual link behaviour.
    await reactorToken.document.setFlag(
        "lancer-automations",
        "ownerActorUuid",
        target.actor.uuid
    );

    await reactorToken.document.setFlag(
        "lancer-automations",
        "ownerName",
        target.actor.name
    );

    // Remove any revision 1/2 item- or actor-attached Boost before creating the separate feature.
    await api.removeExtraActions(item, BOOST_ACTION);
    await api.removeExtraActions(reactorToken.actor, BOOST_ACTION);

    // Remove any embedded Boost left by the earlier implementation.
    const legacyBoostFeature = api.findItemByLid(
        reactorToken,
        "rtm_npcf_follower_count_boost"
    );
    if (legacyBoostFeature)
        await legacyBoostFeature.delete();

    // Add the Boost directly to this Breacher's actor-level action list.
    // Actor extras bind to a general activation with the same exact name.
    await api.removeExtraActions(reactorToken.actor, BOOST_ACTION);
    await api.addExtraActions(reactorToken.actor, {
        name: BOOST_ACTION,
        activation: "Free",
        detail: "Once per turn, Boost up to Speed. Move as close to the followed target as possible.",
        icon: "fas fa-forward"
    });
    return;
}

// -----------------------------------------------------------------------------
// DESTRUCTION CLEANUP
// -----------------------------------------------------------------------------

if (triggerType === "onDestroyed" || triggerType === "onExitCombat") {
    await cleanupFollowerCount();
}

