        return false;

    const otherToken = triggeringToken.id === reactorToken.id
        ? linkedTarget
        : reactorToken;

    // Teleports do not traverse intermediate spaces; only the destination matters.
    if (triggerData.moveInfo?.isTeleport) {
        return api.getMinGridDistance(
            triggeringToken,
            otherToken,
            triggerData.endPos
