// TemplateMacro's targetFilter handles who this runs against.
// Both whenEntered and whenTurnStart use this same tracker.

const applyBurn = `
const la = game.modules.get("lancer-automations")?.api;

if (!la || !token?.actor)
    return;

const swarm = template.getFlag("lancer-automations", "razorSwarm");

if (!swarm)
