// -----------------------------------------------------------------------------
// HELPERS
// -----------------------------------------------------------------------------

const sceneTokens = canvas.tokens.placeables;

const cleanupDenied = async sanctuaryId => {
    if (!sanctuaryId)
        return;

    await api.removeEffectsByNameFromTokens({
        tokens: sceneTokens,
        effectNames: ["Sanctuary Denied"],
        extraFlags: {
