    });
};

// -----------------------------------------------------------------------------
// SANCTUARY REMOVED
// -----------------------------------------------------------------------------
// This catches every way Sanctuary can end:
//
// - native end-of-next-turn expiry
// - refreshing/replacing the mark
// - destruction cleanup
//
// Any Denied marker belonging to that Sanctuary instance ends with it.

if (triggerType === "onStatusRemoved") {
    const flags =
        triggerData.effect?.flags?.["lancer-automations"] ?? {};

    await cleanupDenied(flags.sanctuaryId);
    return;
}

// -----------------------------------------------------------------------------
// PRIEST DESTROYED
// -----------------------------------------------------------------------------
// Sanctuary explicitly ends when its Priest is destroyed.

if (triggerType === "onDestroyed") {
    const markedTokens = api.findMarkedTokens(
        reactorToken,
        "Sanctuary",
        {
            flagKey: "sanctuarySourceId"
        }
    );

    // Collect the instance IDs before deleting the marks so their related
