    const sanctuaryIds = markedTokens.flatMap(target =>
        api.findEffectsOnToken(
            target,
            "Sanctuary",
            {
                extraFlags: {
                    sanctuarySourceId: reactorToken.id
                }
            }
        )
        .map(effect =>
            effect.flags?.["lancer-automations"]?.sanctuaryId
        )
        .filter(Boolean)
    );

    for (const sanctuaryId of sanctuaryIds)
        await cleanupDenied(sanctuaryId);

    await api.clearMarks(
        reactorToken,
        "Sanctuary",
        {
            flagKey: "sanctuarySourceId"
        }
    );

    return;
}

// -----------------------------------------------------------------------------
// APPLY SANCTUARY
// -----------------------------------------------------------------------------

if (triggerType === "onActivation") {
    const targets = await api.chooseToken(reactorToken, {
        range: reactorToken.actor.system.sensor_range,
        count: 1,
        filter: token => api.isFriendly(reactorToken, token),
        filterWarning: "Sanctuary must target an allied character.",
        soft: false,
        includeSelf: true,
        title: "SANCTUARY",
        description: "Choose an allied character within Sensors to protect with Sanctuary."
    });

    if (!targets?.length)
        return;

    const target = targets[0];

    // -------------------------------------------------------------------------
    // REFRESH THIS PRIEST'S SANCTUARY ON THIS TARGET
    // -------------------------------------------------------------------------
    // Other Priests' Sanctuary effects are independent and remain untouched.

    const oldSanctuaries = api.findEffectsOnToken(
        target,
        "Sanctuary",
        {
            extraFlags: {
                sanctuarySourceId: reactorToken.id
            }
        }
    );

    for (const oldSanctuary of oldSanctuaries) {
        const oldId =
            oldSanctuary.flags?.["lancer-automations"]?.sanctuaryId;

        await cleanupDenied(oldId);
        await api.deleteEffect(target, oldSanctuary);
    }

    // -------------------------------------------------------------------------
    // APPLY NEW SANCTUARY MARK
    // -------------------------------------------------------------------------
    // turns: 1 + label: "end" + Priest as duration origin means:
    //
    //     END OF THE PRIEST'S NEXT TURN
    //
    // LA 4.1 handles the current-turn adjustment internally.

    const sanctuaryId = foundry.utils.randomID();

    await api.applyMark(
        reactorToken,
        [target],
        {
            effect: {
                name: "Sanctuary",
                icon: item.img,
                isCustom: true
            },

            note: `Protected by ${reactorToken.name}. Characters must pass a Systems save before attacking this character.`,

            duration: {
                label: "end",
                turns: 1,
                rounds: 0,
                overrideTurnOriginId: reactorToken.id
            },

            flagKey: "sanctuarySourceId",

            extraOptions: {
                sanctuaryId,
                sanctuaryTargetTokenId: target.id
            }
        }
    );

    return;
}

// -----------------------------------------------------------------------------
// ATTACK GATE
// -----------------------------------------------------------------------------
// IMPORTANT:
// cancelAttack/cancelTechAttack must be invoked synchronously, BEFORE any await.
// Their async preConfirm callback is then allowed to perform the Systems save.

if (triggerType === "onInitAttack" || triggerType === "onInitTechAttack") {
    const attacker = triggerData.triggeringToken;

    if (!attacker)
        return;

    // Collect every target of this attack protected by THIS Priest.
    const protectedTargets = [];

    for (const target of triggerData.targets ?? []) {
        const sanctuaries = api.findEffectsOnToken(
            target,
            "Sanctuary",
            {
                extraFlags: {
                    sanctuarySourceId: reactorToken.id
                }
            }
        );

        for (const sanctuary of sanctuaries) {
            protectedTargets.push({
                target,
                sanctuary,
                flags: sanctuary.flags?.["lancer-automations"] ?? {}
            });
        }
    }

    if (!protectedTargets.length)
        return;

    const cancelAttack = triggerType === "onInitAttack"
        ? triggerData.cancelAttack
        : triggerData.cancelTechAttack;

    const userIdControl = api.getTokenOwnerUserId(attacker);

    // -------------------------------------------------------------------------
    // ALREADY DENIED
    // -------------------------------------------------------------------------
    // If this attacker already failed against one of these Sanctuary instances,
    // they cannot target that protected character again until their next turn.

    const alreadyDenied = protectedTargets.find(entry =>
        api.findEffectsOnToken(
            attacker,
            "Sanctuary Denied",
            {
                extraFlags: {
                    sanctuaryId: entry.flags.sanctuaryId
                }
            }
        ).length > 0
    );

    if (alreadyDenied) {
        ui.notifications.warn(
            `${attacker.name} cannot target ${alreadyDenied.target.name} until the start of their next turn.`
        );

        cancelAttack(
            `${attacker.name} has already failed Sanctuary and cannot target ${alreadyDenied.target.name} again this turn. The action is not spent.`,
            "SANCTUARY",
            false,
            userIdControl,
            null,
            null,
            {
                item,
                originToken: reactorToken,
                relatedToken: alreadyDenied.target
            }
        );

        return;
    }

    // -------------------------------------------------------------------------
    // SYSTEMS SAVE
    // -------------------------------------------------------------------------
    // preConfirm executes while the original attack is safely suspended.
    //
    // RETURN FALSE = save passed -> LA re-runs the original attack and skips
    // this reactor on the retry.
    //
    // RETURN TRUE = save failed -> original attack stays cancelled and its
    // action is not spent.

    const sanctuarySave = async () => {
        for (const entry of protectedTargets) {
            const sanctuaryId = entry.flags.sanctuaryId;

            if (!sanctuaryId)
                continue;

            const results = await api.executeSaveVsEffect(
                attacker,
                {
                    stat: "SYS",
                    title: "Sanctuary",
                    origin: reactorToken,

                    effects: {
                        name: "Sanctuary Denied",
                        icon: item.img,
                        isCustom: true
                    },

                    // turns: 0 + start means exactly the start of the attacker's
                    // next turn. No manual _preAdjusted handling is required.
                    duration: {
                        label: "start",
                        turns: 0,
                        rounds: 0,
                        overrideTurnOriginId: attacker.id
                    },

                    note: `Cannot target ${entry.target.name} again until the start of ${attacker.name}'s next turn.`,

                    extraFlags: {
                        sanctuaryId,
                        sanctuarySourceId: reactorToken.id,
                        sanctuaryTargetTokenId: entry.target.id
                    },

                    cardTitle: "SANCTUARY",
                    cardDescription: `${attacker.name} must pass a Systems save against ${reactorToken.name} before attacking ${entry.target.name}.`,
                    sendToOwner: true,

                    onFail: async () => {
                        ui.notifications.warn(
                            `${attacker.name} failed Sanctuary against ${entry.target.name}. The attack is cancelled, but the action is not spent.`
                        );

                    }
                }
            );

            const result = results[0];

            // A cancelled/uncompleted save also leaves the attack safely
            // cancelled rather than allowing it through without a result.
            if (!result?.result?.completed)
                return true;

            if (!result.passed)
                return true;
        }

        // All required Sanctuary saves passed.
        return false;
    };

    cancelAttack(
        `A Systems save is required before ${attacker.name} can attack a character protected by Sanctuary.`,
        "SANCTUARY",
        false,
        userIdControl,
        sanctuarySave,
        null,
        {
            item,
            originToken: reactorToken,
            relatedToken: protectedTargets[0].target
        }
    );
}

reactions.evaluate:
const source = triggerData.triggeringToken ?? triggerData.token;
const targetId = api.getActorFlags(reactorToken.actor, "suppressTargetId");

if (triggerType === "onActivation") {
    return source?.id === reactorToken.id
        && triggerData.item?.id === item.id
        && triggerData.item?.system?.lid === item.system?.lid;
}

if (!targetId)
    return false;

if (triggerType === "onDamage") {
    const damageTotal = (triggerData.damages ?? []).reduce(
        (sum, value) => sum + Math.max(0, Number(value) || 0),
        0
    );
    return source?.id === targetId
        && triggerData.target?.id === reactorToken.id
        && damageTotal > 0;
}

if (triggerType === "onStatusApplied") {
    if (source?.id !== reactorToken.id)
        return false;
    const status = (
        String(triggerData.statusId ?? "") + " " + String(triggerData.effect?.name ?? "")
    ).toLowerCase();
    return status.includes("jammed") || status.includes("stunned");
}

if (triggerType === "onDestroyed")
    return source?.id === reactorToken.id || source?.id === targetId;

if (triggerType === "onExitCombat")
    return source?.id === reactorToken.id;

if (triggerType === "onUpdate") {
    if (source?.id !== reactorToken.id && source?.id !== targetId)
        return false;
    const change = triggerData.change ?? {};
    const moved = Object.prototype.hasOwnProperty.call(change, "x")
        || Object.prototype.hasOwnProperty.call(change, "y")
        || Object.prototype.hasOwnProperty.call(change, "elevation");
    if (!moved)
        return false;
    const target = canvas.tokens.get(targetId);
    return !target || !api.hasLineOfSight(reactorToken, target);
}

return false;

reactions.activationCode:
const getSuppressTargets = () => {
    const targetId = api.getActorFlags(reactorToken.actor, "suppressTargetId");
    const flagged = targetId ? canvas.tokens.get(targetId) : null;
    const marked = api.findMarkedTokens(
        reactorToken,
        "Suppress",
        { flagKey: "suppressSourceId" }
    );
    return [...new Map(
        [flagged, ...marked].filter(Boolean).map(token => [token.id, token])
    ).values()];
};

const clearSuppress = async () => {
    const targets = getSuppressTargets();
    if (targets.length) {
        await api.removeEffectsByNameFromTokens({
            tokens: targets,
            effectNames: ["Suppress", "impaired"],
            extraFlags: { suppressSourceId: reactorToken.id },
            notify: false
        });
    }
    await api.removeActorFlags(reactorToken.actor, {
        suppressTargetId: true,
        suppressLosLost: true
    });
};

const endSuppress = async () => {
    await clearSuppress();
    const active = api.getActivatedItems(reactorToken).some(activeItem => activeItem.id === item.id);
    if (active)
        await api.endItemActivation(item, reactorToken);
};

if (triggerType === "onActivation") {
    if (triggerData.endActivation) {
        await clearSuppress();
        return;
    }

    const targets = await api.chooseToken(reactorToken, {
        range: 10,
        count: 1,
        includeSelf: false,
        disposition: "hostile",
        soft: false,
        autoConfirm: true,
        title: "SUPPRESS",
        description: "Choose a hostile target within line of sight and Range 10.",
        icon: "fas fa-crosshairs",
        filter: target => api.hasLineOfSight(reactorToken, target),
        filterWarning: "Suppress requires line of sight."
    });
    const target = targets?.[0];
    if (!target)
        return;

    // Selecting a new valid target ends the previous Suppress first.
    await clearSuppress();

    await api.applyEffectsToTokens({
        tokens: [target],
        effectNames: [
            { name: "Suppress", icon: item.img, isCustom: true },
            "impaired"
        ],
        note: "Suppressed by " + reactorToken.name,
        duration: { label: "indefinite" }
    }, {
        suppressSourceId: reactorToken.id,
        suppressSourceItemId: item.id
    });

    await api.addActorFlags(reactorToken.actor, {
        suppressTargetId: target.id
    });

    await api.setItemAsActivated(
        item,
        reactorToken,
        "Free",
        "End Suppress"
    );
    return;
}

await endSuppress();

reactions.onInit:
const targetId = api.getActorFlags(token.actor, "suppressTargetId");
if (!targetId)
    return;
const target = canvas.tokens.get(targetId);
if (!target || !api.hasLineOfSight(token, target)) {
    if (target) {
        await api.removeEffectsByNameFromTokens({
            tokens: [target],
            effectNames: ["Suppress", "impaired"],
            extraFlags: { suppressSourceId: token.id },
            notify: false
        });
    }
    await api.removeActorFlags(token.actor, {
        suppressTargetId: true,
        suppressLosLost: true
    });
    const active = api.getActivatedItems(token).some(activeItem => activeItem.id === item.id);
    if (active)
        await api.endItemActivation(item, token);
}

reactions.evaluate:
const mover = triggerData.triggeringToken;

if (!mover)
    return false;

// Rapid Response only triggers from hostile characters.
if (!api.isHostile(reactorToken, mover))
    return false;

// Involuntary movement and teleportation do not provoke reactions.
if (
    triggerData.moveInfo?.isInvoluntary ||
    triggerData.moveInfo?.isTeleport ||
    triggerData.moveInfo?.isUndo
)
    return false;

// The Archer must actually be capable of taking the granted Boost.
const cannotBoost =
    api.findEffectOnToken(reactorToken, "slow") ||
    api.findEffectOnToken(reactorToken, "immobilized") ||
    api.findEffectOnToken(reactorToken, "grappled") ||
    api.findEffectOnToken(reactorToken, "jammed") ||
    api.findEffectOnToken(reactorToken, "stunned");

if (cannotBoost)
    return false;

// The triggering enemy must be in line of sight after their movement.
return api.hasLineOfSight(reactorToken, mover);

reactions.activationCode:
const speed = Number(reactorToken.actor.system.speed ?? 0);

if (speed <= 0)
    return;

// -----------------------------------------------------------------------------
// RAPID RESPONSE — BOOST
// -----------------------------------------------------------------------------
// Fire a real Boost activation through Lancer Automations. It is labelled as
// a Reaction here because Rapid Response grants the Boost without spending the
// Archer's normal Quick Action.
//
// This also lets any other automation that reacts to the Archer using Boost
// recognize Rapid Response as an actual Boost rather than generic free movement.

const boost = await api.executeSimpleActivation(
    reactorToken.actor,
    {
        title: "Boost",
        action: {
            name: "Boost",
            activation: "Reaction"
        },
        detail: "Rapid Response: Boost up to your Speed."
    },
    {
        rapidResponse: true,
        rapidResponseSourceItemId: item.id
    }
);

if (!boost?.completed)
    return;

// The native Boost activation grants the additional movement allowance.
// Immediately provide the interactive movement picker so Rapid Response can
// be resolved in one operation. Movement uses its real cost rather than cost 0,
// allowing movement history/cap tracking to treat it normally.
const moved = await api.moveToken(reactorToken, {
    range: speed,
    title: "RAPID RESPONSE",
    description: `Boost up to ${speed} spaces.`
});

if (!moved)
    return;

// -----------------------------------------------------------------------------

Abjure - Attack Roll Heat.evaluate:
if (!["attackRoll", "techAttackRoll"].includes(triggerData.rollType))
    return false;

// A reroll/changeRoll re-fires onRoll for the same attack flow.
// Abjure should only charge Heat once for each actual attack roll.
if (api.getFlowFlag(triggerData, "abjureAttackHeatApplied"))
    return false;

return api.findEffectsOnToken(
    reactorToken,
    "Abjure",
    { hasFlags: ["abjureHeat"] }
).some(effect =>
    Number(effect.flags?.["lancer-automations"]?.abjureHeat ?? 0) > 0
);

Abjure - Attack Roll Heat.activationCode:
// -----------------------------------------------------------------------------
// ONCE PER ATTACK FLOW
// -----------------------------------------------------------------------------
// Stamp the attack flow so rerolls/changeRoll do not trigger Abjure Heat again.

api.setFlowFlag(
    triggerData,
    "abjureAttackHeatApplied"
);

// -----------------------------------------------------------------------------
// FIND ACTIVE ABJURE EFFECTS
// -----------------------------------------------------------------------------

const abjures = api.findEffectsOnToken(
    reactorToken,
    "Abjure",
    { hasFlags: ["abjureHeat"] }
).filter(effect =>
    Number(effect.flags?.["lancer-automations"]?.abjureHeat ?? 0) > 0
);

// -----------------------------------------------------------------------------
// COUNT ATTACK ROLLS
// -----------------------------------------------------------------------------
// onRoll fires once for the overall attack flow. A multi-target attack contains
// one target result for each individual attack roll, and Abjure triggers for
// EACH of those rolls.

const rollCount = Math.max(
    1,
    triggerData.targets?.length ?? 0
);

// -----------------------------------------------------------------------------
// APPLY ABJURE HEAT
// -----------------------------------------------------------------------------
// Attribution is intentionally unimportant here. The affected character is
// used as both the damage-flow source and target.

for (const effect of abjures) {
    const heat = Number(
        effect.flags["lancer-automations"].abjureHeat
    );

    for (let i = 0; i < rollCount; i++) {
        await api.executeDamageRoll(
            reactorToken,
            [reactorToken],
            heat,
            "Heat",
            "Abjure"
        );
    }
}

Follower Count Boost.evaluate:
if (triggerData.actionName !== "Follower Count Boost")
    return false;
if (triggerData.triggeringToken?.id !== reactorToken.id)
    return false;
return !!api.getActorFlags(reactorToken.actor, "followerCountTargetId");

Follower Count Boost.activationCode:
const turnKey = game.combat?.started
    ? game.combat.id + ":" + game.combat.round + ":" + game.combat.turn
    : null;
const usedTurnKey = api.getActorFlags(
    reactorToken.actor,
    "followerCountBoostUsedTurnKey"
);

if (turnKey && usedTurnKey === turnKey) {
    ui.notifications.warn("Follower Count Boost has already been used this turn.");
    return;
}

const targetId = api.getActorFlags(reactorToken.actor, "followerCountTargetId");
const target = targetId ? canvas.tokens.get(targetId) : null;

if (!target) {
    ui.notifications.warn("Follower Count: " + reactorToken.name + " no longer has a valid target.");
    return;
}

if (api.findEffectOnToken(reactorToken, "immobilized")) {
    ui.notifications.warn("Follower Count: " + reactorToken.name + " is Immobilized and cannot Boost.");
    return;
}

const moved = await api.moveToken(reactorToken, {
    range: Number(reactorToken.actor.system.speed ?? 0),
    cost: 0,
    title: "FOLLOWER COUNT BOOST",
    description: "Move up to Speed. Reminder: finish as close to " + target.name + " as possible."
});

if (!moved)
    return;

if (turnKey) {
    await api.addActorFlags(reactorToken.actor, {
        followerCountBoostUsedTurnKey: turnKey
    });
}
